// ---- Node.js 风格代码示例 (server.node.js) ----
// 需要先安装 express: npm install express
const express = require('express');
const app = express();

app.get('/', (req, res) => {
  res.send('Hello from Node.js!');
});

app.listen(3000, () => {
  console.log('Node.js server running on port 3000');
});

// ---- Deno 风格代码示例 (server.ts) ----
// 无需预先安装，运行命令: deno run --allow-net server.ts
import { Application } from "https://deno.land/x/oak@v12.6.1/mod.ts";

const app = new Application();

// 中间件示例
app.use((ctx) => {
  ctx.response.body = "Hello from Deno!";
});

console.log("Deno server running on http://localhost:8000");
await app.listen({ port: 8000 });

codeExample.explanation:
// Node.js 示例解释:
// 1. `require('express')`: 使用CommonJS语法从本地`node_modules`导入第三方模块。
// 2. 使用Express框架创建了一个简单的HTTP服务器，监听3000端口。
// 3. 代码风格为JavaScript，若使用TypeScript则需额外配置编译器。

// Deno 示例解释:
// 1. `import { Application } from "https://deno.land/x/..."`: 使用ES Modules语法，直接从远程URL导入Oak框架。Deno会自动缓存下载的模块。
// 2. `await app.listen(...)`: 使用`await`是因为Oak的API是基于Promise的，这体现了Deno对现代异步范式的一流支持。
// 3. 文件扩展名是`.ts`，表明这是TypeScript代码，Deno原生支持，无需预编译步骤。
// 4. 要运行此代码，必须在命令行中明确授予网络权限(`--allow-net`)，否则会因安全限制而报错。这体现了Deno的权限沙箱模型。

